// The state file: what it means, and what a half-written one means.
//
// No stand-in for `vscode` here either. The file is generated by whatever
// reads the compiled library, so the reading has to be tolerant, and the
// tolerance is what this pins.
const path = require('path');
const { EMPTY, chip, parse, styleOf } = require(
    path.join(__dirname, '..', 'out', 'state.js'));

let failed = 0;
function check(what, got, want) {
    if (JSON.stringify(got) !== JSON.stringify(want)) {
        console.error(`FAILED: ${what}: got ${JSON.stringify(got)}, want ${JSON.stringify(want)}`);
        failed = 1;
    }
}

const FILE = JSON.stringify({
    palette: {
        formalized: '#1f3a1f',
        sorry: { background: '#5a2d2d', foreground: '#ffffff' },
    },
    nodes: {
        thm_svd: 'formalized',
        def_clm: 'sorry',
        thm_picard: '#333333',       // a colour of its own, with no palette entry
        _part_1_funcanal: '#1f3a5f',  // a whole part
        _ch_08_svd: '#1f3a4f',        // a chapter inside it
    },
});
const states = parse(FILE);
const at = (p) => p.split('/');

// A state name resolves through the palette and keeps its name -- the name is
// what the chip writes beside a section line that already says the label. A
// value the palette does not name is a colour, so a file can be written
// either way.
check('a state name', styleOf(states, 'thm_svd'),
    { background: '#1f3a1f', name: 'formalized' });
check('with a foreground', styleOf(states, 'def_clm'),
    { background: '#5a2d2d', foreground: '#ffffff', name: 'sorry' });
check('a bare colour', styleOf(states, 'thm_picard'), { background: '#333333' });
check('a node the file does not mention', styleOf(states, 'thm_gone'), undefined);

// A path segment colours everything under it, and the deepest one wins: a
// node overrides its chapter, and a chapter its part.
const SVD = at('AutoIp/_part_1_funcanal/_ch_08_svd/_lem_sigma/Spec.lean');
check('a chapter beats its part', styleOf(states, 'lem_sigma', SVD),
    { background: '#1f3a4f' });  // a colour, so no name
check('a part colours its other chapters', styleOf(states, 'lem_x',
    at('AutoIp/_part_1_funcanal/_ch_03_hilbert/_lem_x/Spec.lean')),
    { background: '#1f3a5f' });
check('a label beats both', styleOf(states, 'thm_svd', SVD),
    { background: '#1f3a1f', name: 'formalized' });
check('and nothing matches outside them', styleOf(states, 'lem_y',
    at('AutoIp/_part_2_reg/_ch_12/_lem_y/Spec.lean')), undefined);

// Half-written, mistyped, or not JSON at all. A state file is generated, so
// it is sometimes caught mid-write; that should cost a reader their colours
// and nothing else.
for (const bad of [
    '',
    '{',
    '{"palette": {"a": "#fff"}, "nodes"',
    'null',
    '[]',
    '"a string"',
    '42',
]) {
    check(`unreadable: ${JSON.stringify(bad)}`, parse(bad), EMPTY);
}

// Readable, but with entries that are not what they should be: those are
// dropped one by one rather than taking the file down with them.
const messy = parse(JSON.stringify({
    palette: { good: '#fff', bad: 42, worse: null, arr: [] },
    nodes: { a: 'good', b: 7, c: 'missing' },
    extra: 'ignored',
}));
check('a palette entry that is not a colour', messy.palette.has('bad'), false);
check('null is not an entry', messy.palette.has('worse'), false);
check('an array gives no colours', styleOf(messy, 'arr'), undefined);
check('a good entry survives its neighbours', styleOf(messy, 'a'),
    { background: '#fff', name: 'good' });
check('a node value that is not a string', styleOf(messy, 'b'), undefined);
check('a state the palette does not name is its own colour',
    styleOf(messy, 'c'), { background: 'missing' });

// A file with no palette at all is a colour map, which is the shape a hand
// written one takes.
check('no palette', styleOf(parse('{"nodes":{"thm_svd":"#abc"}}'), 'thm_svd'),
    { background: '#abc' });
check('no nodes', styleOf(parse('{"palette":{"a":"#abc"}}'), 'a'), undefined);

// ------------------------------------------------- what the chip says

// The chip says what its line does not. On a section line -- the one Lean's
// own symbol provider makes sticky -- the label is already written in the
// code, so the chip is for the state.
check('off a section, the label', chip('thm_svd', undefined, false, true), 'thm_svd');
check('and the label whatever the state',
    chip('thm_svd', { background: '#333', name: 'sorry' }, false, true), 'thm_svd');
check('on a section, the state',
    chip('thm_svd', { background: '#333', name: 'sorry' }, true, true), 'sorry');
check('on a section, a bare colour is a swatch',
    chip('thm_svd', { background: '#333' }, true, true), ' ');
check('on a section with nothing to say, nothing',
    chip('thm_svd', undefined, true, true), undefined);

// A node the blueprint does not write outranks all of it. Nothing else in the
// editor reports a library directory the prose has lost, and the state of a
// node that is not in the blueprint is not the thing worth saying.
check('lost, off a section', chip('thm_gone', undefined, false, false),
    'thm_gone is not in the blueprint');
check('lost, on a section, where the label is already written',
    chip('thm_gone', undefined, true, false), 'not in the blueprint');
check('lost, and the state does not speak over it',
    chip('thm_gone', { background: '#333', name: 'formalized' }, true, false),
    'not in the blueprint');

if (failed === 0) {
    console.log('ok: the state file says what it says, and the chip says what its line does not');
}
process.exit(failed);
